import json

with open('/app/resources/treasury_bulletin_1970_06.json', 'r') as f:
    data = json.load(f)

# Search for AY-1 or yield tables
pages = data.get('document', {}).get('pages', [])

for pi, page in enumerate(pages):
    if 'elements' in page:
        for elem in page['elements']:
            if elem.get('type') == 'table':
                # Check table name or content for yield data
                table_str = json.dumps(elem).lower()
                if 'aa' in table_str and 'corporate' in table_str and 'treasury' in table_str:
                    print(f"Found potential yield table on page {pi}")
                    if 'name' in elem:
                        print(f"  Table name: {elem['name']}")
                    # Print dimensions
                    if 'rows' in elem:
                        print(f"  Dimensions: {len(elem['rows'])} rows x {len(elem['rows'][0]) if elem['rows'] else 0} cols")
                    # Print first few rows to understand structure
                    if 'rows' in elem and elem['rows']:
                        print("  First row (cells):")
                        for cell in elem['rows'][0][:6]:
                            print(f"    {cell}")
                    break
EOF
